pub struct FitBaseType(pub u8);

impl FitBaseType {
    pub const ENUM: FitBaseType = FitBaseType(0);
    pub const SINT8: FitBaseType = FitBaseType(1);
    pub const UINT8: FitBaseType = FitBaseType(2);
    pub const SINT16: FitBaseType = FitBaseType(131);
    pub const UINT16: FitBaseType = FitBaseType(132);
    pub const SINT32: FitBaseType = FitBaseType(133);
    pub const UINT32: FitBaseType = FitBaseType(134);
    pub const STRING: FitBaseType = FitBaseType(7);
    pub const FLOAT32: FitBaseType = FitBaseType(136);
    pub const FLOAT64: FitBaseType = FitBaseType(137);
    pub const UINT8Z: FitBaseType = FitBaseType(10);
    pub const UINT16Z: FitBaseType = FitBaseType(139);
    pub const UINT32Z: FitBaseType = FitBaseType(140);
    pub const BYTE: FitBaseType = FitBaseType(13);
    pub const SINT64: FitBaseType = FitBaseType(142);
    pub const UINT64: FitBaseType = FitBaseType(143);
    pub const UINT64Z: FitBaseType = FitBaseType(144);

    pub const NUM_MASK: u8 = 0b00011111;
    pub const ENDIAN_ABILITY_MASK: u8 = 0b00011111;

    const SIZES: [u8; 17] = [1, 1, 1, 2, 2, 4, 4, 1, 4, 8, 1, 2, 4, 1, 8, 8, 8];

    pub const fn size(self) -> u8 {
        let index = (self.0 & FitBaseType::NUM_MASK) as usize;
        if index < FitBaseType::SIZES.len() {
            return FitBaseType::SIZES[index];
        }
        0
    }
}

